fn solve(a: i8, b: i8) -> i8 {
    // Compute a - 2*b in a wider type to avoid overflow,
    // then clamp to zero if it's negative.
    let uncovered = (a as i16) - 2 * (b as i16);
    if uncovered > 0 {
        uncovered as i8
    } else {
        0
    }
}

