    #[test]
    fn basic_cases() {
        // a > 2*b
        assert_eq!(solve(10, 4), 2);   // 10 - 2*4 = 2
        assert_eq!(solve(100, 49), 2); // 100 - 2*49 = 2

        // a == 2*b
        assert_eq!(solve(8, 4), 0);    // 8 - 2*4 = 0

        // a < 2*b
        assert_eq!(solve(7, 4), 0);    // 7 - 2*4 = -1 -> clamp to 0
        assert_eq!(solve(1, 100), 0);  // 1 - 200 = -199 -> clamp to 0

        // edge inputs within [1, 100]
        assert_eq!(solve(1, 1), 0);    // 1 - 2 = -1 -> 0
        assert_eq!(solve(100, 1), 98); // 100 - 2 = 98
    }
